files.design/system/components.css:
/* Generated by dfw from design/system/components/*.html. Do not edit by hand. */

/* button (design/system/components/button.html) */
.btn { display: inline-flex; align-items: center; height: 40px; padding: 0 var(--space-4); border-radius: var(--radius-md); border: 1px solid transparent; font: inherit; }
.btn--primary { background: var(--color-accent); color: var(--color-on-accent); }
.btn--ghost { background: transparent; color: var(--color-ink); border-color: var(--color-border); }
.btn:focus-visible { outline: 2px solid var(--color-accent); }

/* motif (design/system/components/motif.html) */
/* Motifs belong to the "industrial-utility" style. While comparing other option themes, decorative motifs
   are hidden and motifs with content fall back to plain text (content never disappears). */
[data-theme^="opt-"]:not([data-theme="opt-industrial-utility"]) .motif:empty { display: none; }
[data-theme^="opt-"]:not([data-theme="opt-industrial-utility"]) .motif:not(:empty) { all: unset; font-family: var(--font-family-mono); font-size: var(--font-size-sm); color: var(--color-muted); }
.motif--hazard-tape { height: var(--space-2); background: repeating-linear-gradient(-45deg, var(--color-signature) 0 var(--space-3), var(--color-brand) var(--space-3) var(--space-6)); }
.motif--label-tape { display: inline-flex; align-items: center; padding: var(--space-half) var(--space-2); background: var(--color-signature); color: var(--color-brand); font: var(--font-weight-medium) var(--font-size-sm) / 1.2 var(--font-family-mono); letter-spacing: var(--font-tracking-wide); }

