files.design/system/components.css:
/* Generated by dfw from design/system/components/*.html. Do not edit by hand. */

/* button (design/system/components/button.html) */
.btn { display: inline-flex; align-items: center; height: 40px; padding: 0 var(--space-4); border-radius: var(--radius-md); border: 1px solid transparent; font: inherit; }
.btn--primary { background: var(--color-accent); color: var(--color-on-accent); }
.btn--ghost { background: transparent; color: var(--color-ink); border-color: var(--color-border); }
.btn:focus-visible { outline: 2px solid var(--color-accent); }

/* motif (design/system/components/motif.html) */
/* Motifs belong to the "playful-bold" style. While comparing other option themes, decorative motifs
   are hidden and motifs with content fall back to plain text (content never disappears). */
[data-theme^="opt-"]:not([data-theme="opt-playful-bold"]) .motif:empty { display: none; }
[data-theme^="opt-"]:not([data-theme="opt-playful-bold"]) .motif:not(:empty) { all: unset; font-family: var(--font-family-mono); font-size: var(--font-size-sm); color: var(--color-muted); }
.motif--sticker { display: inline-block; padding: var(--space-1) var(--space-3); background: var(--color-signature); color: var(--color-ink); border: var(--border-width-strong) solid var(--color-ink); border-radius: var(--radius-pill); box-shadow: 3px 3px 0 var(--color-ink); transform: rotate(-4deg); font-weight: var(--font-weight-bold); }
.motif--hard-card { border: var(--border-width-strong) solid var(--color-ink); border-radius: var(--radius-lg); box-shadow: 6px 6px 0 var(--color-ink); background: var(--color-surface); padding: var(--space-6); }

