files.design/system/components.css:
/* Generated by dfw from design/system/components/*.html. Do not edit by hand. */

/* button (design/system/components/button.html) */
.btn { display: inline-flex; align-items: center; height: 40px; padding: 0 var(--space-4); border-radius: var(--radius-md); border: 1px solid transparent; font: inherit; }
.btn--primary { background: var(--color-accent); color: var(--color-on-accent); }
.btn--ghost { background: transparent; color: var(--color-ink); border-color: var(--color-border); }
.btn:focus-visible { outline: 2px solid var(--color-accent); }

/* motif (design/system/components/motif.html) */
/* Motifs belong to the "warm-craft" style. While comparing other option themes, decorative motifs
   are hidden and motifs with content fall back to plain text (content never disappears). */
[data-theme^="opt-"]:not([data-theme="opt-warm-craft"]) .motif:empty { display: none; }
[data-theme^="opt-"]:not([data-theme="opt-warm-craft"]) .motif:not(:empty) { all: unset; font-family: var(--font-family-mono); font-size: var(--font-size-sm); color: var(--color-muted); }
.motif--stitch { border: var(--border-width-strong) dashed var(--color-rule); border-radius: var(--radius-lg); padding: var(--space-5); }
.motif--seal { width: var(--space-16); height: var(--space-16); border-radius: var(--radius-pill); display: grid; place-items: center; border: var(--border-width-strong) solid var(--color-accent); color: var(--color-accent); font: italic var(--font-weight-medium) var(--font-size-xl) / 1 var(--font-family-display); transform: rotate(-8deg); }

